@'
import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
const root=path.join(process.env.APPDATA,'npm/node_modules/@vxu-labs/dip');
const sha=s=>createHash('sha256').update(s).digest('hex');
const files=['package.json'];
if(fs.existsSync(path.join(root,'package-lock.json')))files.push('package-lock.json');
for(const dir of ['bin','src','skills'])for(const file of fs.readdirSync(path.join(root,dir),{recursive:true}))if(fs.statSync(path.join(root,dir,file)).isFile())files.push(`${dir}/${file.replaceAll('\\','/')}`);
const fingerprint=sha(JSON.stringify(files.sort().map(f=>[f,sha(fs.readFileSync(path.join(root,f)))])));
const protocol=JSON.parse(fs.readFileSync('docs/benchmarks/2026-10-07-model-protocol-v5.json'));
assert.equal(fingerprint,protocol.installedProduct.fingerprint);
console.log(JSON.stringify({installedVersion:JSON.parse(fs.readFileSync(path.join(root,'package.json'))).version,measuredProductionFingerprintMatches:true,fingerprint}));
const owned=['README.md','QA_REPORT.md','docs/benchmarks/model-controlled-repeat.md','docs/host-qa/lifecycle.md','docs/host-qa/structured-plan.md'];
assert.ok(owned.every(f=>!fs.readFileSync(f,'utf8').includes('\u2014')));
console.log('Authored Markdown contains no em dashes.');
'@ | node --input-type=module
